#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe smtp-log-in-with-cram-md5. Do not edit.
set -e
cd "$(dirname "$0")"
cat > hi.eml <<'EOF'
From: ann@example.com
To: bob@example.com
Subject: Lunch

Noon at the usual place.
EOF
awk '{printf "%s\r\n", $0}' > plain.smtp <<'EOF'
EHLO client
AUTH PLAIN AGFubkBleGFtcGxlLmNvbQBhbm5wYXNz
AUTH PLAIN AGFubkBleGFtcGxlLmNvbQB3cm9uZw==
AUTH LOGIN
QUIT
EOF
cat > decode-login.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Sends hi.eml once with curl -v on the port given, then decodes the two lines of the CRAM-MD5
# login: the server's challenge and curl's answer to it.
curl -v --crlf -u ann@example.com:annpass --mail-from ann@example.com --mail-rcpt bob@example.com \
  -T hi.eml "smtp://127.0.0.1:$1/example.com" 2>&1 |
  tr -d '\r' | sed -n -e '/^> AUTH CRAM-MD5$/{n;s/^< 334 //p;n;s/^> //p;}' |
  while read -r line; do printf '%s' "$line" | base64 -d; echo; done
EOF
surl --mail-domain example.com --mailbox ann@example.com:annpass --mailbox bob@example.com:bobpass smtp://127.0.0.1:8080/ &
sleep 1
curl -sS --crlf -u ann@example.com:annpass --mail-from ann@example.com --mail-rcpt bob@example.com -T hi.eml -w "%{response_code}\n" smtp://127.0.0.1:8080/example.com
kill $(jobs -p)
